import sys,random,time,networkx as nx
sys.path.insert(0,'/workspace/submission')
from fastgen import fast_generate
def build(nt,seed):
 random.seed(seed);n=32
 H=nx.DiGraph();H.add_nodes_from(range(n));loads={};roots={i:0 for i in range(n)}
 for k in range(nt):
  T=[]
  for v in range(1,n):T.append((random.randrange(v),v))
  root=random.randrange(n);w=random.randint(1,10)
  adj={i:[] for i in range(n)}
  for a,b in T:adj[a].append(b);adj[b].append(a)
  st=[root];seen={root}
  while st:
   x=st.pop()
   for y in adj[x]:
    if y not in seen:seen.add(y);loads[(x,y)]=loads.get((x,y),0)+w;st.append(y)
  roots[root]+=w
 for (a,b),c in loads.items():H.add_edge(a,b,capacity=c)
 return H,roots
H,roots=build(300,9300)
orders={
 'idx_asc':sorted(roots),
 'idx_desc':sorted(roots,reverse=True),
 'dem_hi_first':sorted(roots,key=lambda u:(-roots[u],u)), # appended high->low, pop low first actually name
 'dem_lo_first':sorted(roots,key=lambda u:(roots[u],u)),
}
for name,order in orders.items():
 t=time.time();Ts,Cs=fast_generate(H,list(range(32)),roots,initial_order=order);print(name,'time',time.time()-t,'trees',len(Ts),flush=True)
